<script setup lang="ts">import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ServiceProvider} from '@/services/service-provider';import type {User} from '@/types/user';const route=useRoute();const router=useRouter();const users=ref<User[]>([]);const loading=ref(false);const error=ref('');const q=ref(String(route.query.q||''));const page=computed(()=>Math.max(1,Number(route.query.page||1)));const limit=10;const showCreate=ref(false);const form=ref({firstName:'',lastName:'',email:'',username:'',password:'',age:18,gender:'',phone:''});async function load(){loading.value=true;error.value='';try{users.value=await ServiceProvider.users.getAll({limit,skip:(page.value-1)*limit,q:q.value})}catch(e){error.value=(e as Error).message}finally{loading.value=false}}function search(){router.push({query:{q:q.value||undefined,page:1}})}function change(delta:number){router.push({query:{q:q.value||undefined,page:page.value+delta}})}async function createUser(){try{const created=await ServiceProvider.users.create(form.value);users.value=[created,...users.value];showCreate.value=false}catch(e){error.value=(e as Error).message}}async function deleteUser(id:number){if(!confirm('Видалити цього користувача?'))return;try{await ServiceProvider.users.delete(id);users.value=users.value.filter(user=>user.id!==id)}catch(e){error.value=(e as Error).message}}watch(()=>route.fullPath,load,{immediate:true})</script>
<template><section><div class="page-heading"><div><p class="eyebrow">SECURE AREA</p><h1>Користувачі</h1></div><button class="button" @click="showCreate=!showCreate">＋ Додати</button></div><form v-if="showCreate" class="card create-form" @submit.prevent="createUser"><h3>Новий користувач</h3><div class="form-grid"><label>Ім'я<input v-model="form.firstName" required/></label><label>Прізвище<input v-model="form.lastName" required/></label><label>Email<input v-model="form.email" type="email" required/></label><label>Username<input v-model="form.username" required/></label><label>Password<input v-model="form.password" minlength="6" required/></label><label>Телефон<input v-model="form.phone" required/></label></div><button class="button">Створити</button></form><div class="toolbar"><input v-model="q" placeholder="Пошук користувача..." @keyup.enter="search"/><button class="button" @click="search">Знайти</button></div><p v-if="loading" class="state">Завантаження...</p><p v-else-if="error" class="error state">{{error}}</p><div v-else class="user-grid"><div v-for="user in users" :key="user.id" class="user-card"><RouterLink class="user-main" :to="`/users/${user.id}`"><img :src="user.image" alt=""/><div><strong>{{user.firstName}} {{user.lastName}}</strong><small>{{user.email}}</small><small>@{{user.username}}</small></div></RouterLink><button class="delete-button" title="Видалити" @click="deleteUser(user.id)">×</button></div></div><div class="pagination"><button :disabled="page===1" @click="change(-1)">← Назад</button><span>Сторінка {{page}}</span><button :disabled="users.length<limit" @click="change(1)">Далі →</button></div></section></template>
